Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAXN = 262144;

int L, n, k, mod, len;
int fac[MAXN], inv[MAXN], popcnt[MAXN], g[20][MAXN], f[20][MAXN];
vector<int> bits;
ll h[20], p[20];

inline int mod_pow(int x, int y) {
    int res = 1;
    while (y) {
        if (y & 1) res = (ll)res * x % mod;
        x = (ll)x * x % mod;
        y >>= 1;
    }
    return res;
}

inline void f_add(int &x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}

inline void f_sub(int &x, int y) {
    x -= y;
    if (x < 0) x += mod;
}

void fwt(int *a, int m) {
    for (int i = 1; i < m; i <<= 1)
        for (int j = 0; j < m; j += i << 1)
            for (int k = 0; k < i; k++)
                f_add(a[j + k + i], a[j + k]);
}

void ifwt(int *a, int m) {
    for (int i = 1; i < m; i <<= 1)
        for (int j = 0; j < m; j += i << 1)
            for (int k = 0; k < i; k++)
                f_sub(a[j + k + i], a[j + k]);
}

void poly_ln() {
    p[0] = 0;
    for (int i = 1; i <= n; i++) {
        p[i] = h[i] * i;
        for (int j = 1; j < i; j++)
            p[i] -= p[j] * h[i - j] % mod * j;
        p[i] = p[i] % mod * inv[i] % mod;
    }
    for (int i = 0; i <= n; i++) h[i] = (p[i] + mod) % mod;
}

void poly_exp() {
    p[0] = 1;
    for (int i = 1; i <= n; i++) {
        p[i] = 0;
        for (int j = 1; j <= i; j++)
            p[i] += h[j] * p[i - j] % mod * j;
        p[i] = p[i] % mod * inv[i] % mod;
    }
    for (int i = 0; i <= n; i++) h[i] = p[i];
}

int main() {
    scanf("%d%d%d", &L, &k, &mod);
    int all = mod_pow(k, L);

    if (L & 1) {
        printf("%d\n", all);
        return 0;
    }

    fac[0] = 1;
    for (int i = 1; i <= L; i++) fac[i] = (ll)fac[i - 1] * i % mod;

    inv[L] = mod_pow(fac[L], mod - 2);
    for (int i = L - 1; i >= 0; i--) inv[i] = (ll)inv[i + 1] * (i + 1) % mod;

    for (int s = 1; s <= L; s++) popcnt[s] = popcnt[s ^ (s & -s)] + 1;

    for (int i = 0; i < 19; i++)
        if ((L >> i) & 1) bits.push_back(1 << i);

    n = (int)bits.size();
    len = 1 << n;

    for (int mask = 0; mask < len; mask++) {
        int s = 0;
        for (int j = 0; j < n; j++)
            if ((mask >> j) & 1) s += bits[j];
        g[popcnt[mask]][mask] = inv[s];
    }

    for (int i = 2; i <= n; i++)
        inv[i] = (ll)(mod - mod / i) * inv[mod % i] % mod;

    for (int i = 0; i <= n; i++) fwt(g[i], len);

    for (int mask = 0; mask < len; mask++) {
        for (int i = 0; i <= n; i++) h[i] = g[i][mask];
        poly_ln();
        for (int i = 0; i <= n; i++) h[i] = h[i] * k;
        poly_exp();
        for (int i = 0; i <= n; i++) f[i][mask] = h[i];
    }

    ifwt(f[n], len);

    int ans = (ll)f[n][len - 1] * fac[L] % mod;
    ans = (all - ans + mod) % mod;

    printf("%d\n", ans);
    return 0;
}
